def predict(train,query):
    ix={g:i for i,g in enumerate(GENES)}
    sim=KERNEL[np.ix_([ix[g] for g in query['genes']],[ix[g] for g in train['genes']])]
    w=np.exp((sim-sim.max(1,keepdims=True))/0.15);w/=w.sum(1,keepdims=True)
    norm=np.linalg.norm(train['Y'],axis=1)
    directions=train['Y']/np.maximum(norm[:,None],1e-12)
    pred=0.75*np.mean(norm)*(w@directions)
    f=CORRELATIONS[[ix[g] for g in train['genes']]]
    q=CORRELATIONS[[ix[g] for g in query['genes']]]
    center=f.mean(0)
    residual=train['Y']-train['Y'].mean(0)
    mapping=Ridge(alpha=10,fit_intercept=False).fit((f-center).reshape(-1,3),residual.ravel())
    correction=mapping.predict((q-center).reshape(-1,3)).reshape(len(q),-1)
    pred=pred+0.5*correction
    go=query['E']@train['E'].T;c=np.clip((go.max(1)-0.9)/0.05,0,1)
    donor=go.argmax(1)
    trusted=0.5*train['Y'][donor]+0.5*np.mean(norm)*directions[donor]
    return (1-c[:,None])*pred+c[:,None]*trusted
